WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[27909] = { title = "The Purespring", description = "Helgrum's breathing slows. His time is near.\n\nI need water. Elementals roam the ponds of Purespring Cavern. The water that flows from them is the purest in this swamp.\n\nEven if I could risk leaving Helgrum's side, my axe would shudder in my hand. I must beg you once again to pity me, for his comfort. Bring me the motes of the elementals, that his final drink may be pure and refreshing.", objectives = "Collect 8 Purespring Motes from Purespring Elementals.", progress = "You've returned.", completion = "He can only drink so much. The rest might be used for washing his body, after...\n\n<Neeka glares in frustration and shudders, turning her head away.>" }
WordHunterWoW_QuestEN[27910] = { title = "Last Regrets", description = "If I am reduced to groveling, I may as well ask everything I can. There is one last favor I would ask of you, one more task a shamed orc pleads for.\n\nHelgrum had a prized prey. Duskfang, eater of ogres, the great panther of Misty Valley. He would never allow himself the leisure of stalking it. Though he wanted badly to hunt, our scouting duties were too important.\n\nIf he cannot hunt Duskfang in this world, he can hunt the beast in the next. Take up the hunt for him; bring Duskfang's pelt to me.", objectives = "Collect Duskfang's Hide.", progress = "Has Duskfang shown himself?", completion = "With Duskfang to shroud his body, he will carry the animal's spirit with him into the afterlife.\n\nListen to me. An old superstitious fool. I'm so sorry, Helgrum..." }
WordHunterWoW_QuestEN[27911] = { title = "With Dying Breath", description = "He stirs...\n\nDo not leave, {name}. Please, honor Helgrum with me. You have done so much for him.", objectives = "Witness Helgrum's last moments.", completion = "He is gone.\n\nHe is right. I must be strong for him..." }
WordHunterWoW_QuestEN[27912] = { title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", objectives = "Investigate the Trove of the Watchers.", completion = "You peer into the chest..." }
WordHunterWoW_QuestEN[27913] = { title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", objectives = "Investigate the Trove of the Watchers.", completion = "You peer into the chest..." }
WordHunterWoW_QuestEN[27914] = { title = "Blessing of the Green Dragonflight", description = "You have done well, {name}. Jammal'an may have escaped our grasp, but his retreat paves the way for me to enter the temple as I desire.\n\nStay where you are and do not move. I will hasten your return by pulling your spirit to me through the Emerald Dream.\n\nThis may cause slight drowsiness.", objectives = "Speak with Lord Itharius atop the Temple of Atal'Hakkar.", completion = "You have performed a great service for me and my kind, <name>. Accept this as a symbol of my gratitude, and of your courage." }
WordHunterWoW_QuestEN[27915] = { title = "The Heart of the Temple", description = "I must confess I have a more personal involvement in this affair. One of the first of the green dragons corrupted here was my brother, Eranikus.\n\nI thought Eranikus gone, lost forever to the darkest rifts of nightmare, but I have heard that his shade has emerged within the temple. I know not whether it is truly him, or an empty, mournful echo.\n\nIf you wish to help me further, return to the Hall of Masks and journey through the archway into the true sanctum of the temple. I will find you there.", objectives = "Speak with Lord Itharius again inside the Temple of Atal'Hakkar.", completion = "I am pleased to see you once again, <name>. You are truly noble to assist me further." }
WordHunterWoW_QuestEN[27916] = { title = "Ruag's Report", description = "Here is Ruag's report, {name}. Let him know his scout is still here.\n\nDo not speak of Helgrum. I will not distract others with news of tragedy.\n\nI have to be strong. We all have to be strong.", objectives = "Deliver the Splinterspear Report to Dispatch Commander Ruag in Stonard.", progress = "Yes?", completion = "<Ruag reads over the report.>\n\nI see.  Thank you for this information, <name>." }
WordHunterWoW_QuestEN[27917] = { title = "Sniffing Them Out", description = "I could smell Godfrey and his companions a mile away from here. They did an exceedingly poor job covering their tracks in flight. It will be the mistake that puts the final nail in their coffins.\n\nOne of them is very close, and though the scent has changed slightly in undeath, I'm fairly certain it's Ashbury's. Go inside and tear him to pieces, we'll ensure the Forsaken do not intervene with our task.", objectives = "Kill Baron Ashbury.", progress = "Kill Ashbury before I lose my patience. You wouldn't like me when I'm angry...", completion = "The scent of freshly spilled traitor blood fills my nostrils, and it is absolutely invigorating. However, my bloodlust will not be sated until Godfrey lies on the floor as a lifeless heap.\n\nHe thinks an army of mindless corpses can stop the wrath of the Bloodfang? We'll gnaw on their bones for years to come after our work is done!" }
WordHunterWoW_QuestEN[27918] = { title = "The Harborage", description = "Anchorite Avuun is one of our uncorrupted brethren, what other races know as Draenei. He came to The Harborage to heal us, and try to find a cure. It is he who sent me here to collect these crystals.\n\nHe watches over a very sick friend now... and despite sending word to the Exodar itself, he has not found any aid so far. Could you bring these crystals to him, {name}? You may be the only one able to assist him.", objectives = "Deliver the Draenethyst Crystals to Anchorite Avuun.\n\nProvided item:", completion = "Thank you, <class>. I am afraid it may be too late... but I refuse to give up, even if the Exodar itself does not hear my cries." }
WordHunterWoW_QuestEN[27919] = { title = "Onward to the Blasted Lands", description = "We appreciate your assistance here in this swamp, {name}.  I would like to inform you that I have received correspondence from Nethergarde Keep.\n\nEnohar Thunderbrew has requested help in investigating the shipwrecks of the Red Reaches, but we have had none willing to make the journey, and I could not leave the Harborage.\n\nNethergarde Keep sits in the Blasted Lands, south of the Swamp of Sorrows.  Do not journey too close to Stonard on your way.", objectives = "Journey to the Blasted Lands and speak with Enohar Thunderbrew in Nethergarde Keep.", completion = "Ah, has Avuun sent ye? Good, good..." }
WordHunterWoW_QuestEN[27920] = { title = "Armored to the Teeth", description = "We've hit an unexpected snag in our assault on the keep, {name}. It seems the servants that tended to Baron Silverlaine and Commander Springvale in life do so now in death as well, and Godfrey has placed them directly between us and him.\n\nNot to worry, we won't let them be anything more than a minor inconvenience. Eliminate Silverlaine and Springvale both and not only will their guards no longer have masters to direct them, it will place us that much closer to our final goal.", objectives = "Kill Baron Silverlaine and Commander Springvale.", progress = "It is infuriating that we have to kill these ghost soldiers when they are completely outside the main objective, but it must be done. Godfrey is a cunning foe indeed.", completion = "We're nearly there, <name>. The time is now to charge further ahead and take out Walden!" }
WordHunterWoW_QuestEN[27921] = { title = "Fighting Tooth and Claw", description = "It appears that Lord Walden has finally taken notice to our presence and has heightened his defenses. It's worthless really... nothing will deter our pack.\n\nThe path ahead to him is rife with powerful Scourge minions, but I trust that you will be able to clear the path for the rest of us to follow in. Once we kill Walden, it should be a straight shot to his cowardly leader.", objectives = "Kill Lord Walden.", progress = "We're behind you, <name>.", completion = "<Packleader Ivar Bloodfang grins, revealing his razor-sharp teeth.>\n\nIt won't be long now before the entire keep is ours, thanks to your valiant efforts." }
WordHunterWoW_QuestEN[27922] = { title = "Traitors!", description = "Please, stranger.  You must help me.\n\nI came here to investigate the arrival of a powerful ally to the Neferset, only to be betrayed by my closest allies and given up to the enemy.\n\nGo to the terrace above us to the east and find the information I failed to uncover.  You'll need to hide from the Neferset.  Perhaps you can hide behind one of the large plants on the platform to conceal your presence.\n\nDo this for me and I will help your friends find their way to safety.", objectives = "Hide behind the Neferset Frond and Uncover the Neferset Secret.", progress = "What did you witness, <name>?", completion = "A djinn!  We must escape as soon as possible.\n\nThis unholy alliance of the Neferset with the minions of Deathwing does not bode well for us." }
WordHunterWoW_QuestEN[27923] = { title = "Smoke in Their Eyes", description = "I'm not sure what knuckle-headed plan your friend is concocting, but we're going to need a distraction if we're to stand a chance of escaping.\n\nTake the torch from that brazier and go start some fires.\n\nPerhaps if we divert the Neferset scum's attention away for a few minutes, we'll have the opportunity we need.", objectives = "Burn Stacks of Hay inside the Lost City of the Tol'vir in Uldum.", completion = "Yes.  I hear the Neferset calling each other to the east.  This might yet work." }
WordHunterWoW_QuestEN[27924] = { title = "Budd's Plan", description = "I've an idea!  Trust me, it's a good one this time!\n\nGet some of those shiny armor pieces the cat-people wear.\n\nThis plan cannot fail.  Trust me.", objectives = "Obtain 6 pieces of Neferset Armor.", progress = "Did you get the pieces, <name>?", completion = "Excellent.  You'll see, this can't possibly go wrong!" }
WordHunterWoW_QuestEN[27925] = { title = "Efficient Excavations", description = "This manual describes outlandish theories on how to efficiently manage large groups of workers as they engage in the manual labor of various types of excavation.\n\nIt becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nPerhaps an introduction is in order.", objectives = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:" }
WordHunterWoW_QuestEN[27926] = { title = "Eastern Hospitality", description = "The commander is quite busy now, I'm afraid.\n\nThe demands of an operation such as this require much of his attention these days.\n\nWhile you wait to speak with him, why don't you mingle with some of our guests?\n\nWe have invited a variety of Azeroth's most illustrious figures to be present when we unlock the secrets of this region.\n\nI am confident that you will find them most captivating.", objectives = "Belloc Brightblade wants you to mingle with the guests at Schnottz's Landing.", completion = "I trust that you had no troubles fitting in with our guests, hmm?" }
WordHunterWoW_QuestEN[27927] = { title = "Down to the Scar", description = "The Badlands are home to some unusual people, many of whom have been here for quite a long time.\n\nFor example, there were three gentlemen who were staying here in town.  I forget their names... the dwarf was Theldurin, I think?  Anyhow, they headed south with a pack full of ale a couple of days ago, and haven't been heard from since.  I think they were headed to that big scar.\n\nWould you mind checking in on them?  I'd like to make sure that they're alright.", objectives = "Find Theldurin the Lost at the Scar of the Worldbreaker in the Badlands.", completion = "They sent you to check up on us?  Pshh... I've been around this desert longer than any of those chumps.  We're just soaking in some of the scenery and telling stories about old times.\n\nYou like telling stories?" }
WordHunterWoW_QuestEN[27928] = { title = "A Favor for the Furrier", description = "The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him.\n\nBefore building up his... ehh... workforce, he dealt in the furs of animals.\n\nHe is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts.\n\nThe dried oasis to the east is said to be home to a rare breed of coyote.\n\nTheir furs would make a very thoughtful gift.", objectives = "Collect 5 Desert Coyote Pelts.", progress = "Were you successful in your hunt?", completion = "Oh, these are exquisite!\n\nThe commander will be able to make a winter uniform with these." }
WordHunterWoW_QuestEN[27929] = { title = "Drag 'em Down", description = "A single Dragonmaw drake is worth a dozen Wildhammer gryphon-riders. Take them off of their lice-ridden birds and they're nothing.\n\nEven you can slay them easily, Horde-{class}.\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Finish them! Kill a few Thundermar gryphon riders and I'll believe your Horde is as mighty as you say.", objectives = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", completion = "You look a little battered. Those dwarves didn't give you any challenge, did they?\n\nStill, that was an impressive show." }
WordHunterWoW_QuestEN[27930] = { title = "Devastation", description = "The coast is clear.  If Rheastrasza or the egg were able to miraculously evade Deathwing's flames, they would probably need your assistance as soon as possible.", objectives = "Search for Rheastrasza.", completion = "Heroes:\n\nIf you are reading this, then my suspicions were correct.  Deathwing has found us.  The egg is destroyed, as am I.\n\nThis was, actually, the plan from the beginning.  You see... the egg that Deathwing destroyed was not the egg he sought.\n\nIt was mine." }
WordHunterWoW_QuestEN[27931] = { title = "The Quaking Fields", description = "Before you can help us here, you're going have to deal with Therazane, the Stone Mother's, forces to the south. The elementals and giants upon the Quaking Fields are being mustered.\n\nThey too are after the middle fragment of the World Pillar. They'll attack us amidst our war with the stone troggs and we'll be unable to repel them.\n\nI've sent the arch geomancer ahead. Get to Slate Quicksand and do as he asks.", objectives = "Speak with Slate Quicksand at the Quaking Fields in Deepholm.", completion = "Good, <race>, you're here.\n\nWe'll have to act fast if we're to prevent Therazane's forces from attacking." }
WordHunterWoW_QuestEN[27932] = { title = "The Axe of Earthly Sundering", description = "The emerald colossi are the greatest of the Stone Mother's creatures. They must be the first to be removed from the field.\n\nI brought Stonefather Oremantle's axe for just this task. Use it to sunder the giants.\n\nThat should bring them down to a more manageable size for you to finish off.", objectives = "Slay 5 Sundered Emerald Colossi.", completion = "Thank you, <name>. Without all of their giants, Therazane's forces will have a harder time taking Stonehearth.\n\nNow, if you please, hand back the axe. I'll keep it safe until you can rescue the Stonefather." }
WordHunterWoW_QuestEN[27933] = { title = "Elemental Ore", description = "You're going to have to deal with the leader of Therazane's forces here. However, to get you to him quickly and safely, I'm going to need to perform a ritual.\n\nGo out into the field and collect elemental ore from the ragers. With enough of it, I should be able to make you one with the ground to get you where you need to go.", objectives = "Collect 6 Elemental Ore.", progress = "Have you all that is required?", completion = "These should do. I'll just need a moment to prepare the ritual." }
WordHunterWoW_QuestEN[27934] = { title = "One With the Ground", description = "The leader of the Stone Mother's forces here is the great earth elemental lord, Avalanchion. Luckily for us, the Twilight's Hammer cultists have decided to invade his lair. They're seeking to bind his elementals to their will.\n\nWe will take advantage of the chaos. The earth ritual that I invoke will make you one with the ground. It will take you near to Avalanchion without alerting him to your presence.\n\nIt's up to you to finish him.", objectives = "Complete the One With the Ground ritual." }
WordHunterWoW_QuestEN[27935] = { title = "Bring Down the Avalanche", description = "Avalanchion stands before you. Slay him to keep Therazane's forces from attacking Stonehearth.", objectives = "Slay Avalanchion.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, <name>. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?" }
WordHunterWoW_QuestEN[27936] = { title = "Bring Down the Avalanche", description = "You have to go back and slay Avalanchion to keep Therazane's forces from attacking Stonehearth!", objectives = "Slay Avalanchion.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, <name>. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?" }
WordHunterWoW_QuestEN[27937] = { title = "The Hero Returns", description = "The Stonefather is waiting for you back south at Stonehearth.\n\nMake yourself presentable. You've earned a hero's welcome!", objectives = "Present yourself to Stonefather Oremantle at Stonehearth in Deepholm.", completion = "Our hero returns!\n\nYou have saved my people, <name>. You have earned that which you seek." }
WordHunterWoW_QuestEN[27938] = { title = "The Middle Fragment", description = "I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar.\n\nKeep the fragment safe, {name}. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible!\n\nKnow that you are always welcome here.", objectives = "Recover the Middle Fragment of the World Pillar.", progress = "You've returned. Did you recover the middle fragment?", completion = "The Middle Fragment of the World Pillar!\n\nThank you, <name>. I can only imagine what you had to go through to get this to us. I'll see to it that it's placed within the center of the chamber." }
WordHunterWoW_QuestEN[27939] = { title = "The Desert Fox", description = "Zhere is much to be done in zhis region, {race}.\n\nVe bozh haf a burning passion for zhe ancient technologies here, do ve not?\n\nPerhaps zhere is a vay for us to vork togezher?\n\nLet us put zhe misunderstandinks of zhe past behind us zhen, hmm?\n\nNow, zhere is an elusive animal in zhe region to zhe east zhat I have been huntink. Brink me zhis creature as a token of your sincerity, hmm?\n\nZhen maybe I let you in on my operation...", objectives = "Schnottz wants you to bring him the Desert Fox.", progress = "Have you captured zhe Desert Fox, <class>?", completion = "You've done it!\n\nPerhaps I can trust you vizh more serious matters, hmm?" }
WordHunterWoW_QuestEN[27940] = { title = "Dirty Birds", description = "The sky above the Shriveled Oasis is littered with these nasty vultures.\n\nLike infectious rodents with wings, these creatures serve no great purpose and inflict untold misery.\n\nRid the skies of this nuisance and leave the region better than you found it.", objectives = "You are to slay 8 Diseased Vultures." }
WordHunterWoW_QuestEN[27941] = { title = "Fashionism", description = "We have a strict policy among our ranks, one that we take most seriously.\n\nOur troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful!\n\nWe call it, Fashionism.\n\nWe've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty.\n\nYou should find plenty of the poor fellows east of here, at the Ruins of Ammon.", objectives = "Belloc Brightblade wants you to collect 10 Trooper Uniforms.", progress = "Were you able to recover the uniforms we need?", completion = "Most efficient work, <class>.\n\nYou should rise rapidly through the ranks." }
WordHunterWoW_QuestEN[27942] = { title = "Idolatry", description = "Zhere is somezhink I need handled, {race}.\n\nMy most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings!\n\nI haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual.\n\nI vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce!\n\nDismissed!", objectives = "Commander Schnottz wants you to collect 8 Well-preserved Idols.", progress = "Haff you brought me zhe idols, <race>?", completion = "Zhese look to be of sufficient quality.\n\nVizh zhese, ve are vone shtep closah to zhe cleansink ritual." }
WordHunterWoW_QuestEN[27943] = { title = "Angered Spirits", description = "Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery.\n\nHe did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence.\n\nIt is of key importance in zhe ritual I vill be attemptink.\n\nVhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material.\n\nZhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.", objectives = "Commander Schnottz wants you to use the L.P.A.C. to collect 5 Furious Spectral Essences.", progress = "Vell, little man? Vere you successful?", completion = "Very goot!\n\nYou have earned yourself a place at zhe ritual.\n\nYou shall be among zhe first to velcome Gobbles back to his... original form." }
WordHunterWoW_QuestEN[27944] = { title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Horde troops nearby earlier in the week.", objectives = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", completion = "Nice work on those spiders <name>.  At this rate, we will be taking that forest in no time." }
WordHunterWoW_QuestEN[27945] = { title = "Paint it Black", description = "The ground bleeds, {class}. They tear it open, as one would gouge flesh.\n\nThese cultists relish their secrecy but the very elementals they use for their misdeeds can betray them. Seek out Obsidian Stoneslaves northeast of here, among the ruined earth we have named the Black Breach.\n\nShatter their bodies and find for me a perfect heart of black diamond. I will look into this heart. And I will bare its soul.", objectives = "Acquire a Black Diamond Heart.", progress = "The heart. A stone heart, of purest black. Have you found one?", completion = "<Mallia removes her eyepatch and holds the black diamond before her empty eye socket.>\n\nWhat have we, what have we - breaches, the breaches number three. Two heads, one wholly given to its master. I see the future. A hammer united. A mountain shattered. Oh - OH!\n\n<Mallia drops the diamond to the floor, covering her face with her hands.>" }
WordHunterWoW_QuestEN[27946] = { title = "NYI", description = "", objectives = "" }
WordHunterWoW_QuestEN[27947] = { title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through powerful magical orbs: \"The Eyes of Twilight.\"\n\nIn Mount Hyjal, the Guardians of Hyjal managed to find and manipulate one to their own ends. We must do the same. I want one of those orbs, and I want to use it to peer into the very heart of Cho'gall's lair.\n\nSearch the Black Breach, across the river to the northeast, and find an Eye of Twilight. Do whatever you need to bring it back to me!  ", objectives = "Locate an Eye of Twilight within the Black Breach.", completion = "<The Eye sits before you, humming ominously with dark energies.>\n\n<Without warning, the orb rotates, as if to look at you. You sense a malevolent presence, as though the orb is alive.>" }
WordHunterWoW_QuestEN[27948] = { title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just west of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", objectives = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, <name>." }
WordHunterWoW_QuestEN[27949] = { title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", objectives = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Darkwood and The Restless Front.", progress = "Were you able to release our forgotten brothers in arms?", completion = "May their souls rest in peace." }
WordHunterWoW_QuestEN[27950] = { title = "Gobbles!", description = "At last! Zhe time has come to set my Gobbles free of zhat nasty curse!\n\nPay attention now, {race}, and stay on guard. Zhere can be no interruptions vhile I perform zhe ritual.\n\nLet me know vhen you haf secured zhe perimeter!\n\nNow, move it!", objectives = "Schnottz wants you to speak with him when you are prepared to witness the ritual." }
WordHunterWoW_QuestEN[27951] = { title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", objectives = "Slay 10 Shaman of the Black.", progress = "I have been watching you, <race>.", completion = "<The Eye glimmers darkly, colors swirling about its dusky surface.>\n\nAh, the succulent thrill of life extinguished. Do you feel it, <class>? Do you relish it as I do?\n\nNo, I see not. You fight to protect the lives of others. Pity." }
WordHunterWoW_QuestEN[27952] = { title = "The Explorers", description = "We have a contingent of the Explorers' League in the chamber just to the northwest inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", objectives = "Speak with Explorer Mowi at the Temple of Earth in Deepholm.", completion = "Oh gosh! Someone's finally here to help us?" }
WordHunterWoW_QuestEN[27953] = { title = "The Reliquary", description = "We have a contingent of the Reliquary in the chamber just to the northeast inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", objectives = "Speak with Examiner Rowe at the Temple of Earth in Deepholm.", completion = "Ah, it's about time someone came to speak with us on matters most urgent." }
WordHunterWoW_QuestEN[27954] = { title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to Garona Halforcen.\n\nOh yes, I already know where you're taking me. Garona's relentless quest for vengeance is no secret. It will be a delight to watch it unfold.", objectives = "Take the Eye of Twilight to Garona Halforcen at Bloodgulch in Twilight Highlands.", progress = "Did you have any luck within the Black Breach?", completion = "You found one? I've been searching everywhere. Give it here!\n\nSome of these eyes are won over with riddles or verse. Others require magic. What did this one demand? Ah, it's no matter. What matters is that it's ours." }
WordHunterWoW_QuestEN[27955] = { title = "Eye Spy", description = "This terrible thing makes my hair stand on end. Cho'gall uses these to control his minions - now it's time to use it against him.\n\nLet me see... hmm, it's all cloudy. All I can see is you. Why is it showing me you?\n\n<Garona sets the eye out in front of her.>\n\nLook into the eye and tell me what you see. Peer into Cho'gall's lair! What is he doing? Is he heavily guarded? Tell me!", objectives = "Peer into the Eye of Twilight for Garona.", completion = "You've gone pale, <class>. What did the Eye show you?\n\nYou saw Cho'gall? Wait - Cho'gall saw you? He's watching us? He's watching us right now!?\n\nDamn this stupid dark magic! I'm going to have to infiltrate Cho'gall's stronghold myself." }
WordHunterWoW_QuestEN[27956] = { title = "Lunk's Task", description = "Lunk came from the Badlands.  Other ogres try to make Lunk fight.\n\nLunk hate fighting.  Lunk want to learn.\n\nLunk sees machines to the south.  Machines made of gears.\n\nMaybe if you ask nicely, machines will give you some gears?  Then maybe Lunk can have a gear, and learn about machines too.", objectives = "Obtain 15 Tempered Flywheels from Tempered War Golems.", progress = "You get gears?  How you get them?", completion = "You didn't... KILL the machines to get these, right?.\n\n<Lunk looks upset.>\n\nRight?" }
WordHunterWoW_QuestEN[27957] = { title = "Lunk No Kill", description = "", objectives = "No!  You are the same as Thorium Brotherhood dwarf.\n\n\"Kill dwarf.  Kill spider.  Kill machine.  Kill, kill, kill.\"\n\nLunk come to gorge to go on adventure, not to go on murder spree.\n\nGoodbye, <race>.  You kill too much." }
WordHunterWoW_QuestEN[27958] = { title = "A Proper Antivenom", description = "Shame that Lunk left.  I was beginning to enjoy his company.\n\nOh well, back to work!\n\nI'm the closest thing that this expedition has to a medical officer, and I'm running low on antivenom.  We tend to need a lot of antivenom.\n\nThe key to a proper antivenom is ALWAYS to start with the poison itself.  The glassweb spiders nearby should be a good place to start.  If you kill them, you can probably extract some venom from the sacs within their jaws.", objectives = "Obtain 14 samples of Glassweb Venom.", progress = "Well well, you certainly operate quickly!  You do have the venom, right?", completion = "This... this is way more than I expected.  This will last us for months!" }
WordHunterWoW_QuestEN[27959] = { title = "Lunk's Adventure: Spider Rider", description = "Lunk sees you like to kill things.  Let Lunk teach you another way.\n\nLunk always wanted to ride on spider's back.  Looks like fun.  Spiders move too fast, though.  Always slip away.\n\nWe work together.  You fight spider until it gets weak and tired.  Then Lunk jump on spider's back and ride around.\n\nMaybe Lunk even gather some venom for you!  No have to kill!", objectives = "Weaken 7 Glassweb Spiders so Lunk can ride them." }
WordHunterWoW_QuestEN[27960] = { title = "The Fewer, the Better", description = "I'm not much of a fighter... I'm more of a mining dwarf.  Same goes for Jack and Pris.  And Lunk... well, you'd think he'd be a big fighter, but he's the biggest wimp of all of us.\n\nWhat I'm saying is, it's good that you came here when you did.\n\nIt seems likely that we in the Thorium Brotherhood are going to be fighting the other Dark Iron dwarves soon.  I'm thinking we should pick off some of their finest before the war starts in earnest.  Start with the geologists and watchmen to the south.", objectives = "Slay 10 Dark Iron Geologists or Dark Iron Watchmen.", progress = "The fewer of them that remain, the better our prospects are.", completion = "Thank you." }
WordHunterWoW_QuestEN[27961] = { title = "Out of Place", description = "The gorge is an unforgiving place.  We don't get a whole lot of fuzzy wildlife wandering around here.\n\nWe tried bringing in some wild game, but they haven't fared well at all.  There's just no food for them to eat.  Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat.\n\nWe'll never get rid of all the spiders, but we can salvage what few chickens remain.  Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.", objectives = "Obtain 8 Ash Chickens.", progress = "Those poor animals.", completion = "You've got quick hands if you were able to gather this many in such a short time.\n\nExcellent work, <name>.  I'll make sure these ones don't go to waste." }
WordHunterWoW_QuestEN[27962] = { title = "A Lumbering Relic", description = "Margol the Rager's an old thunder lizard seen round these parts.  Legend has it that he's been here in the gorge since before it was even a gorge.  Legend also has it that he ate my brother Barnabas.\n\nI don't care how old he is or what kind of magic he shoots out of his nose.  I just want him dead.  For Barnabas' sake.\n\nYou'll find him wandering the cliffs to the south of here.", objectives = "Obtain Margol's Gigantic Horn.", progress = "Bring me the horn, <name>.", completion = "Yup, this was Margol's horn alright.  No doubt about it.\n\nBarnabas was a digger, like me.  He never stood a chance in combat against the beast.  I'm glad you were here to set things right." }
WordHunterWoW_QuestEN[27963] = { title = "A New Master... But Who?", description = "You've arrived just in time.\n\nHere's the skinny: the Dark Iron dwarves in the gorge have been acting strangely, and the Thorium Brotherhood intends to find out why.  Overseer Oilfist doesn't like surprises.\n\nWe suspect that they're following orders from some new leader.  I have reason to believe that Gravius Grimesilt, just south of here, knows who it is.\n\nEven here in Searing Gorge, we've begun to hear tales of your exploits, {name}.  You should have no problem with Grimesilt.", objectives = "Obtain the Dark Iron Memo from Gravius Grimesilt at Grimesilt Worksite.", progress = "Any news?", completion = "Let's see... Overseer Maltorius... we're quite familiar with him and his work.\n\nWhat's this?  The \"archduke\"?  That sounds promising." }
WordHunterWoW_QuestEN[27964] = { title = "Dig-Boss Dinwhisker", description = "Grimesilt wasn't as high up on the chain as I thought.  We'll have to take out his superior and find out what he knows.\n\nDig-Boss Dinwhisker's his name, and he runs the Dark Iron digging operations within the Cauldron, just northwest of here.  His excavators and footmen patrol the eastern side of the Cauldron, digging downward, day and night.\n\nHe's not known to show his face out in the field very often, but if you slay enough of his men, he'll be forced to come out and deal with you.", objectives = "Kill Dark Iron Excavators and Dark Iron Footmen within the Cauldron until Dig-Boss Dinwhisker appears. Then slay Dig-Boss Dinwhisker and obtain his Dark Ember.", progress = "If Dinwhisker doesn't have what we seek, I'm not sure what we'll do next.", completion = "A... an ember?  What is this thing?" }
WordHunterWoW_QuestEN[27965] = { title = "Thorium Point: The Seat of the Brotherhood", description = "Did... did you see that?  This is the missing piece we've been looking for!  We have to take this information back to someone at Thorium Point.\n\nThe Dark Irons have been known to consort with the firelord in the past, but never before have they brought their kind this far out into Searing Gorge.\n\nThorium Point is west and north of here.  You will find it nestled in the cliffs that overlook Pyrox Flats.  Take this information straight to Overseer Oilfist.", objectives = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "Do I know you, <race>?\n\n\n\nSounds like another one of Ragnaros' minions.  I don't like the sound of that." }
WordHunterWoW_QuestEN[27966] = { title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", objectives = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, <name>.  You are just full of surprises aren't you?" }
WordHunterWoW_QuestEN[27967] = { title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in the Stormwind stockades.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", objectives = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive." }
WordHunterWoW_QuestEN[27968] = { title = "Fury of the Pack", description = "Ah, the sweet scent of victory! My men should be tearing Godfrey to pieces even as we speak. Go up to his domain and collect your share of the spoils - you've earned it!\n\nYou'd think that he would have been more difficult to defeat...", objectives = "Kill Lord Godfrey.", progress = "Let's get going.", completion = "We did it, <name>! At terrible cost... but victory is ours.\n\nThis keep could serve well as a home for me and my pack, though we tend to prefer more natural habitats.\n\nIt may be best to leave it as a reminder of Godfrey's betrayal and of the Bloodfang warriors that died here in battle." }
WordHunterWoW_QuestEN[27969] = { title = "Make Yourself Useful", description = "Gobbles vill be sorely missed, but zhe mission must not suffer.\n\nPerhaps zhere is somezhink you can do to redeem yourself.\n\nTake vone of zhe uniforms you recovered. Vhile vearink it, my vorkers vill not behave so... aggressively.\n\nLately, zheir morale has been a bit lackink. Some of zhe vorkers are refusing to perform zheir labors.\n\nAuch, zhe audacity!\n\nFind zhese lazy imbeciles and convince zhem zhat zhey must get to vork... or else!", objectives = "Commander Schnottz wants you to persuade 6 Slacking Laborers to get to work.", completion = "Vell done, <class>.\n\nZhere may be hope for you yet." }
WordHunterWoW_QuestEN[27970] = { title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", objectives = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", completion = "You did it!  Maybe we can finally get some ships into port now.  Thank you <name>." }
WordHunterWoW_QuestEN[27971] = { title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for horde, we have been getting reports of them ambushing the beach lately.", objectives = "Camp Coordinator Brack has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", completion = "Nice work on the undead up there <name>.  We really appreciate the help." }
WordHunterWoW_QuestEN[27972] = { title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", objectives = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast.", progress = "Were you able to recover the rum?  I would try but I am deathly afraid of the water.  Not to mention that crazy shark.", completion = "This rum will really help us out, <name>.  They might not feel great in the morning but at least they will go to sleep happy." }
WordHunterWoW_QuestEN[27973] = { title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", objectives = "Sergeant Gray has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, <name>.  You are just full of surprises aren't you?" }
WordHunterWoW_QuestEN[27974] = { title = "This Land is Our Land", description = "Did you think that a handful of worgen vermin could stop me? Hah!\n\nShadowfang Keep was part of the Lordaeron kingdom in life, so it is quite fitting that it should belong to the Forsaken in death. Godfrey and his accomplices are minor obstacles at best, and of course we're all happy to take them out for their treachery against the Dark Lady.\n\nAshbury has positioned himself near the front of the keep, leaving him wide open to attack. Start us out on the right foot, would you?", objectives = "Kill Baron Ashbury.", progress = "Don't test my patience and good will.", completion = "Ah, very well done! They've gotten a hold of powerful allies, but clearly nothing a <class>-champion of the Banshee Queen can't handle!" }
WordHunterWoW_QuestEN[27975] = { title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of filthy Horde all around the area.", objectives = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found northwest of here, on the western coast.", completion = "Great work <name>.  I will report your efforts to our highest in command immediately." }
WordHunterWoW_QuestEN[27976] = { title = "Curse These Fat Fingers", description = "Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem.  Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand.  They're like gigantic Thelsamar Blood Sausages, they are...\n\nYe're gonna have to carry out me orders of business and what have ye.\n\nFirst on me agenda: Poundin' the livin' daylights out o' the heavy war golems o' the Gorge.  Get crackin'.", objectives = "Kill 12 Heavy War Golems.", completion = "Ye're a good lad, ye are. I got ye a lil' present fer yer troubles." }
WordHunterWoW_QuestEN[27977] = { title = "Recon Essentials", description = "We used to have more stuff around here.  I think there was a spyglass somewhere nearby, along with a smithing tuyere.\n\nI'm pretty certain that they've been stolen by Dark Iron dwarves.  Yes, I know that I'm a Dark Iron dwarf!  I'm talking about the bad ones that live down in that gorge.\n\nYou'd best check the steamsmiths that work just south of here.  They'd be most likely to use tools like these.", objectives = "Find and return the Smithing Tuyere and Lookout's Spyglass.", progress = "If you're here for the reward, you're gonna have to give me the stolen goods.", completion = "Fantastic work!" }
WordHunterWoW_QuestEN[27978] = { title = "Ghostbuster", description = "See that hill just beyond our base camp?  That's Largo's Overlook and it's not a fun place to setup camp next to.  We have been dealing with those spirits and spectres ever since we setup base camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", objectives = "Kill 14 ghosts of any type at Largo's Overlook, just northeast of base camp.", progress = "Who's afraid of ghosts?  Not me.  Well, maybe in the dark.", completion = "Great work, <name>!  We should not hear from the ghosts again anytime soon." }
WordHunterWoW_QuestEN[27979] = { title = "Dark Ministry", description = "I got one more assignment for ye.  This one comes straight down from the Overseer himself.  Seems he was pretty shook up once he heard about that \"Archduke\" ye discovered.\n\nHe's asked for us to hunt down three Twilight ministers that work over in Firewatch Ridge, to the west.  Kiyuubi, Letherio, and Finister are their names, and they each carry some sort o' special rock.  Combine all three and bring 'em back here.\n\nListen, when the Overseer gives orders, ye don't ask questions.  Ye just do it.", objectives = "Obtain Kiyuubi's Spherule, Letherio's Spherule, and Finister's Spherule, then combine them into a Twilight Tripetricine.", progress = "Ye got the thing?", completion = "<Hansel weighs the stone in his hands.>\n\nThis thing is strange, <name>.  I don't know what to make of it.  It ain't natural, that's for sure." }
WordHunterWoW_QuestEN[27980] = { title = "The Spiders Have to Go", description = "Normal-size spiders, I can handle.\n\nGiant glassweb spiders make me uncomfortable, but they're far enough away that I don't worry too much.\n\nBut lava spiders?  <Lolo shudders.>  Lava spiders are SCARY.  They're enormous spiders.  That live in LAVA.\n\nI just got paid for my last week of work, and I'll pay you well to kill those things.  You'll find 'em all over Searing Gorge.  ", objectives = "Slay 9 Lava Spiders within Searing Gorge.", completion = "There's no way you coulda killed all the spiders in the gorge, but you definitely made a dent.\n\nFine, here's what I promised ya.  Don't spend it all in one place.  Unless it's at Thorium Point." }
WordHunterWoW_QuestEN[27981] = { title = "Heat That Just Don't Quit", description = "We smith, we smelt, we roast up whatever spider meat we can get.  Bush chicken if we're lucky.  Point is, all o' this work means we need lots and lots of fire.\n\nGood thing we're smack dab in the middle of firetown.\n\nO' course, the best fire comes from the elementals.  You'll find 'em all over Searing Gorge, but always near lava.  Here, take these flasks and use 'em on the elementals.\n\nOh, did I mention the elementals gotta be alive when you gather your sample?", objectives = "Obtain 10 Filled Furnace Flasks. You must use the Furnace Flasks on living elementals within Searing Gorge.", progress = "Oilfist says he's gonna have us makin' firebombs soon.  All the more need for those flasks.", completion = "Yeeeeeeowch!  Don't just go puttin' this stuff into a dwarf's open hand.  This stuff is burnin' up!\n\nNow me hands are gonna get even more swollen..." }
WordHunterWoW_QuestEN[27982] = { title = "Twilight Collars", description = "Have ye seen the ridiculous necklaces those Twilight's Hammer cultists all wear?  The gems on those things are bigger than Hansel's fist!\n\nA few hamburger-sized jewels like that, and Burninate over there could really push his blacksmithing business to the next level.  Fetch those collars, and he'll make it worth your while.", objectives = "Obtain 20 Twilight Collars.", progress = "A ruby-hilted hammer... it has a nice ring to it.", completion = "Hmm... the gems looked... sparklier from afar.  Up close, they look kind of dingy.\n\nAh well!  A little spit and polish should do the trick, and if not, I can use 'em to practice my disenchanting." }
WordHunterWoW_QuestEN[27983] = { title = "Lunk's Adventure: Cranky Little Dwarfs", description = "What you doing?  Why you kill?\n\nYou need to get things from dwarfs?  Ah, Lunk understand.  Lunk have a better way.\n\nListen: you go fight dwarf, but do not kill!  Just fight until dwarf get tired.  Then Lunk will help dwarf fall asleep.  Dwarfs probably just cranky because they don't get sleep.\n\nCome on!  Trust Lunk.", objectives = "Weaken 7 Dark Iron Steamsmiths so Lunk can help them fall asleep." }
WordHunterWoW_QuestEN[27984] = { title = "Lunthistle's Tale", description = "Will you assist me, mortal? Hear my tale.", objectives = "Hear Zamael tell his tale.", progress = "Allow me to finish my story.", completion = "I have accepted my fate here in this cage, but the prayer must be found." }
WordHunterWoW_QuestEN[27985] = { title = "Prayer to Elune", description = "Will you assist me, mortal?  Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet.  I believe they hold it within one of their vile chests, near the entrance to their cave at the bottom of the ridge.\n\nIf you do recover my prayer, don't bring it back to me.  Instead, take the time to read through it.\n\nAbsolution may be asking too much, based on the sins I've committed.  But that won't stop me from holding out hope.", objectives = "Find and read the Prayer to Elune." }
WordHunterWoW_QuestEN[27986] = { title = "In the Hall of the Mountain-Lord", description = "The Thorium Brotherhood doesn't maintain a militia - just a few guards, and me, and that's it.  If we're to successfully strike against the Dark Irons of the gorge, we're gonna need help.\n\nMountain-Lord Rendan sits atop that tower across the gorge, to our south.  He doesn't consort with Twilight folks or fire elementals, but he hasn't joined the brotherhood either.  Maybe it's time we paid him a visit.  With his help, we might just stand a chance.", objectives = "Speak with Mountain-Lord Rendan at Iron Summit in Searing Gorge.", completion = "And who might you be?\n\nAh, an emissary from the Thorium Brotherhood.  They're looking for my support?  Fine, I might be willin' to help out...\n\n...for a price." }
WordHunterWoW_QuestEN[27987] = { title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for horde too.", objectives = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Sergeant Gray. You can find Largo's Overlook just northeast of the base camp.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort <name>. These cannonballs should last us a while." }
WordHunterWoW_QuestEN[27988] = { title = "Plague...Plague Everywhere!", description = "The best part about this plague is that even when it visually fades away, the remaining residue is still quite potent! However, we still have an enormous area to cover before we're done, with plenty of Godfrey's defenses in the way.\n\nIt appears that the spirits that served Baron Silverlaine and Commander Springvale in life now guard them in death, and Godfrey is using them to deter us. Show them all the iron will of the Forsaken!", objectives = "Kill Baron Silverlaine and Commander Springvale.", progress = "A couple bodiless spirits aren't going to best you, are they?", completion = "Cromush has both a thick skull and a fool's brain, and we'll use that to our advantage. By the time anybody finds out about the plague's true potency, it'll be far too late.\n\nThank you for keeping quiet during his tirade. I promise you won't regret it." }
WordHunterWoW_QuestEN[27989] = { title = "Ruumbo Demands Honey", description = "Ruumbo hungers!\n\nThe Deadwood jerks have stolen all their honey from the Timbermaw tribe! We saw...er, Ruumbo saw them do it! Now Ruumbo must have that honey!\n\nTake this... this stick! Yes, this stick. Take this stick and use it to steal the honey from their beehives in Deadwood Village.\n\nRuumbo must have as much honey as possible. This is vital.", objectives = "Collect 10 Deadwood Honey Globs from the hives in Deadwood Village using Ruumbo's Honey Stick.", progress = "Ruumbo can smell whether you have honey or not!", completion = "Honey! Delicious honey!\n\nWell done, ugly creature! You may put the honey...put the honey down right there. No, to the left. Yes, there. Just leave it there." }
WordHunterWoW_QuestEN[27990] = { title = "Battlezone", description = "It vould appear zhat anozher opportunity has arisen for you to redeem yourself, {race}.\n\nZhis little emergency has set me back a few tank gunnahs.\n\nYou zhink you have vhat it takes to fill in for vone of zhem?\n\nMy tanks are just vest of zhe camp. Get out zhere and put an end to zhis silliness!", objectives = "Commander Schnottz wants you to man one of the siege tank turrets and use it to defeat 7 Decrepit Watchers, then report back to him.", completion = "Auch!\n\nIf I vere an inch or two taller, I'd be dead!" }
WordHunterWoW_QuestEN[27991] = { title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", objectives = "Sergeant Gray has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", completion = "Ha, we finally got Largo!  Nice one, <name>." }
WordHunterWoW_QuestEN[27992] = { title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", objectives = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", progress = "Did that magnet contraptaion actually work?", completion = "These parts will really help us out, <name>!  Who would have thought you can find stuff this useful in all that old junk?" }
WordHunterWoW_QuestEN[27993] = { title = "Take it to 'Em!", description = "We was lucky to escape, {class}. I'm not sure I'd feel right if we didn't take care of them ambushers.\n\nHows about you git back up to Khartut's tomb and give them little buggers what fer!\n\nIt's off to the northeast, just inside the entrance to Uldum if'n I recollect correctly.\n\nWhat're you looking at? I sure ain't in no condition to do it!", objectives = "Mack wants you to investigate Khartut's Tomb.", completion = "Good to see ya, kid.\n\nWould've been even better if you'd have been here to help me take care of these little savages..." }
WordHunterWoW_QuestEN[27994] = { title = "Ruumbo Demands Justice", description = "You! Wanderer! Bow before the might of Ruumbo, great god of the Timbermaw tribe!\n\nHear my will! The evil Deadwood tribe lives in the village behind me! They are big jerks!\n\nI mean, they... they sully my name with their wicked misdeeds! They persecute my cherished Timbermaw tribe and hurt them!\n\nI demand you inflict my justice! Defeat the Deadwood and I will give you my... my favor! Yes! The favor of RUUMBO! ", objectives = "Slay 15 Deadwood Furbolg of any type.", completion = "It worked!\n\nI mean, uh, YES, the will of Ruumbo has been carried out! You have done well, creature! You may have these shiny coins!" }
WordHunterWoW_QuestEN[27995] = { title = "Dance for Ruumbo!", description = "You have done well, {race}! Ruumbo is pleased by your bravery, and the delicious honey you have given Ruumbo.\n\nNow, you must... you must dance! Yes!\n\nDance for Ruumbo! Dance!", objectives = "Do a silly dance for Ruumbo.", completion = "Those two brats... I should have known! They were smart enough to hush whenever I went to examine the totem.\n\nI'll be sure to find them and drag them back to Timbermaw Hold by the ears! Thank you for looking into it..." }
WordHunterWoW_QuestEN[27996] = { title = "Orders Are For the Living", description = "Unsurprisingly, we aren't going to listen to Cromush about the plague. However, his brute strength will come in handy for muscling my men through the many foes ahead on the path to Godfrey, the most powerful being his right hand man, Lord Walden.\n\nI'll meet you in Walden's chamber after you finish him off. Then, at long last, we can completely take Shadowfang Keep for the Forsaken!", objectives = "Kill Lord Walden.", progress = "You have your orders, <name>.", completion = "The time has come! Godfrey will fall!" }
WordHunterWoW_QuestEN[27997] = { title = "The Corruption of the Jadefire", description = "The cleansing of this forest has been a grueling process. For every success we have achieved, a new challenge has arisen.\n\nThe Jadefire satyr have been a constant nuisance. They seek to corrupt the forest just as we seek to cleanse it. Now, we have taken steps to begin eradicating them from Felwood entirely.\n\nTravel to Jadefire Glen to the west and rid the forest of their presence. You'll find the entrance just north of the walls of Deadwood Village; look for their vile banners.", objectives = "Slay 12 Jadefire Satyr or Jadefire Felsworn in Jadefire Glen.", progress = "Jadefire Glen is our first target in a series of coordinated efforts. The others will be dealt with in time.", completion = "The Emerald Circle thanks you, <name>. If we all work together here, we can purge these demons from our midst." }
WordHunterWoW_QuestEN[27998] = { title = "Sweet, Merciless Revenge", description = "If all goes well you'll just be able to walk right into Godfrey's personal domain and take a reward fitting for such an eager young {class}.\n\nGodfrey is a cunning foe, though, so it may be wise to head up there quickly just in case you're needed. He will pay for what he did to the Dark Lady!", objectives = "Kill Lord Godfrey.", progress = "Let's get going.", completion = "For a moment there, I thought all was lost. Even when surrounded by the worgen in Gilneas I had higher hopes!\n\nBut you proved me wrong <name>. I will see to it that Sylvanas herself hears of your triumph here today. Don't worry about the mess here, I will gladly see to it myself." }
WordHunterWoW_QuestEN[27999] = { title = "The Fate of the Doyles", description = "It seems the Doyles already joined their last fight. Iain will want to know of their fate.", objectives = "Return the news of Clan Doyle to Iain Firebeard at the Firebeard Cemetery.", completion = "That's a right shame. Stubborn as they were to speak to, they were just as stubborn in a fight. Would have been good to have 'em.\n\nOnce this is done, we'll have to send some boys out to bring them back for a proper send off." }
WordHunterWoW_QuestEN[28000] = { title = "Do the Imp-Possible", description = "The satyr hide their corrupted moonwell behind an impenetrable barrier of demonic fire. Their forces must have some way of getting through it.\n\nInterrogating the satyr will be useless, but the imps they consort with will be easily swayed. I have a specific one in mind, as well...\n\nIn the foothills to the east, a lone imp has been seen wandering, far from the other demons. He should prove easy pickings. Weaken him with combat, and then use this enchanted sack to capture him. Then I'll do the talking...", objectives = "Weaken Impsy and use the Enchanted Imp Sack to capture him.", progress = "Do you have an imp for me?", completion = "Imps are creatures of deception. With so many of them spotted at Shadowlurk Ridge, I'm positive something is being hidden there.\n\nOur little friend will tell us exactly how to find it... if he doesn't want to go back in the sack." }
WordHunterWoW_QuestEN[28001] = { title = "A Coward's Due", description = "We may be safe here, but there are a lot of Wildhammer who could still use support. Our wing can offer that, but we need to keep bolsterin' our forces if we're going to clear the Twilight completely.\n\nI'm going to have words with Colin Thundermar. Only a coward turns down the callin' of his people, especially in a time this dire.\n\nGo to Thundermar, find Colin and get a real explanation out of'm. I won't be putting up with cowardice in a Wildhammer leader.", objectives = "Speak to Colin Thundermar in Thundermar.", completion = "Here here, WOT!? He calls ME a COWARD!?\n\nJust like a Firebeard, all hot air and not a lick of sense. I've been bearing the brunt of a Dragonmaw invasion from the south, much of Thundermar is in ruins, and do any of the other clans stick up to help? NO! Ol' Thundermar is on his own he is, and you'd better believe I'm usin' everything in my arsenal just to stem the tide." }
WordHunterWoW_QuestEN[28002] = { title = "Crisis Management", description = "There is a delicate situation that calls for the... objective discretion of an outsider.\n\nYou see, an unfortunate incident has upset some of our guests. Rest assured, our top men are sorting out the details.\n\nIn the meantime, it would be wonderful if you could calm our more squeamish visitors.\n\nHandle this well, and the furrier is sure to hear of it!", objectives = "Belloc Brightblade wants you to reassure the guests at Schnottz's Landing.", completion = "Hmm, still a bit frazzled, are they?\n\nWell, you know what they say. Time heals all wounds.\n\nExcept for those of the ambassador, of course..." }
WordHunterWoW_QuestEN[28003] = { title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Searing Blade is poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Stone Guard Kurjack, head of the defense initiative, to end the threat to Orgrimmar once and for all.", objectives = "Speak with Stone Guard Kurjack.The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Searing Blade is poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Stone Guard Kurjack, head of the defense initiative, to end the threat to Orgrimmar once and for all.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[28004] = { title = "Adventurers Wanted: The Deadmines", description = "The Warchief has requested that any able-bodied adventurer head to the Deadmines, in the distant land of Westfall, immediately!\n\nAssistance is required in the initiative to take the Defias Juggernaut for the Horde to use against the Alliance! If you so choose, head to the Deadmines and speak with Kagtha, a rogue of the Shattered Hand, to aid in the ongoing war against the Alliance.", objectives = "Speak with Kagtha.The Warchief has requested that any able-bodied adventurer head to the Deadmines, in the distant land of Westfall, immediately!\n\nAssistance is required in the initiative to take the Defias Juggernaut for the Horde to use against the Alliance! If you so choose, head to the Deadmines and speak with Kagtha, a rogue of the Shattered Hand, to aid in the ongoing war against the Alliance.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[28005] = { title = "Adventurers Wanted: The Deadmines", description = "King Anduin Wrynn has requested that any able-bodied adventurer head to the Deadmines, in southern Westfall, immediately!\n\nAssistance is required in stopping the reborn Defias Brotherhood from terrorizing the area! If you so choose, head to the Deadmines and speak with Lieutenant Horatio Laine, lead investigator on the case, to aid in stopping the Defias once and for all.", objectives = "Speak with Lieutenant Horatio Laine.King Anduin Wrynn has requested that any able-bodied adventurer head to the Deadmines, in southern Westfall, immediately!\n\nAssistance is required in stopping the reborn Defias Brotherhood from terrorizing the area! If you so choose, head to the Deadmines and speak with Lieutenant Horatio Laine, lead investigator on the case, to aid in stopping the Defias once and for all.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[28006] = { title = "Adventurers Wanted: Wailing Caverns", description = "The Warchief has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", objectives = "Speak with Nalpak.The Warchief has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.You will receive:\n\nUpon completion of this quest you will gain:" }
