WordHunterWoW_QuestEN[28008] = { title = "Adventurers Wanted: Shadowfang Keep", description = "The Warchief has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to Sylvanas! If you so choose, head to Shadowfang Keep and speak with Deathstalker Commander Belmont, leader of the war effort there, to help enact proper revenge.", objectives = "Speak with Deathstalker Commander Belmont.The Warchief has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to Sylvanas! If you so choose, head to Shadowfang Keep and speak with Deathstalker Commander Belmont, leader of the war effort there, to help enact proper revenge.You will receive:\n\nUpon completion of this quest you will gain:" }
