WordHunterWoW_QuestEN[28768] = { title = "Winterspring!", description = "Donova Snowden, dwarf woman, is friend of the Timbermaw.\n\nWe trade firewater.\n\nShe is at Frostfire Hotsprings, to the east, through our cave.\n\nShe needs help to beat up the Winterfall furbolg.  Maybe you will help her.", objectives = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", completion = "Thank goodness you're here. I've discovered the secret of the fierce Winterfall furbolg." }
