WordHunterWoW_QuestEN[28798] = { title = "Waters of Elune", description = "You've found an unusual fountain; the water glows like moonlight and hums with soft tones.  With a Highborne Scroll, and your impressive skill in archaeology, you could decipher the fountain's purpose.", objectives = "You've found an unusual fountain; the water glows like moonlight and hums with soft tones.  With a Highborne Scroll, and your impressive skill in archaeology, you could decipher the fountain's purpose.", progress = "You've found an unusual fountain; the water glows like moonlight and hums with soft tones.  With a Highborne Scroll, and your impressive skill in archaeology, you could decipher the fountain's purpose.", completion = "After a few moments, you are able to use the keystone and reveal the secret of the water...." }
WordHunterWoW_QuestEN[28799] = { title = "Might of the Earthen", description = "At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently.  If you had a Dwarf Rune Stone, its originations could be brought to light.", objectives = "At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently.  If you had a Dwarf Rune Stone, its originations could be brought to light.", progress = "At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently.  If you had a Dwarf Rune Stone, its originations could be brought to light.", completion = "Ah ha!  You knew you'd seen this level of craftsmanship before.  Now, with the final piece..." }
WordHunterWoW_QuestEN[28800] = { title = "Whispers of the Djinn", description = "This brazier is obviously magical, but it seems impervious to your attempts to invoke its power.  If only you had a Tol'vir Heiroglyphic keystone to help decipher the engravings on the side.", objectives = "This brazier is obviously magical, but it seems impervious to your attempts to invoke its power.  If only you had a Tol'vir Heiroglyphic keystone to help decipher the engravings on the side.", progress = "This brazier is obviously magical, but it seems impervious to your attempts to invoke its power.  If only you had a Tol'vir Heiroglyphic keystone to help decipher the engravings on the side.", completion = "It appears as if this particular brazier has trapped a minor djinn, and freeing him would certainly bring a reward.  Right?" }
WordHunterWoW_QuestEN[28801] = { title = "Tol'vir Hieroglyphics", description = "This gravestone marks a strange burial site - possibly from one of the original builders.  If you could use a Tol'vir Hieroglyphic keystone to understand the words, it could be an important archaeological find!", objectives = "This gravestone marks a strange burial site - possibly from one of the original builders.  If you could use a Tol'vir Hieroglyphic keystone to understand the words, it could be an important archaeological find!", progress = "This gravestone marks a strange burial site - possibly from one of the original builders.  If you could use a Tol'vir Hieroglyphic keystone to understand the words, it could be an important archaeological find!", completion = "Using the keystone, you confirm the grave is from one of the original builders, and you learn important details of the mummification process." }
WordHunterWoW_QuestEN[28802] = { title = "Map of the Architects", description = "This stone obelisk is obviously some sort of layout or map, but it isn't completely readable.  Perhaps if you had a Tol'vir Hieroglyphic keystone, the markings might make more sense.", objectives = "This stone obelisk is obviously some sort of layout or map, but it isn't completely readable.  Perhaps if you had a Tol'vir Hieroglyphic keystone, the markings might make more sense.", progress = "This stone obelisk is obviously some sort of layout or map, but it isn't completely readable.  Perhaps if you had a Tol'vir Hieroglyphic keystone, the markings might make more sense.", completion = "Yes... 'X' marks the spot!  This is a detailed map of the dungeon, a valuable find indeed." }
WordHunterWoW_QuestEN[28803] = { title = "Vengeance of the Wildhammer", description = "These old bones appear dwarven, possibly from the original builders of Grim Batol.  It's possible you could compare the markings on the stone belt buckle to a Dwarf Rune Stone, and discover more about this find.", objectives = "These old bones appear dwarven, possibly from the original builders of Grim Batol.  It's possible you could compare the markings on the stone belt buckle to a Dwarf Rune Stone, and discover more about this find.", progress = "These old bones appear dwarven, possibly from the original builders of Grim Batol.  It's possible you could compare the markings on the stone belt buckle to a Dwarf Rune Stone, and discover more about this find.", completion = "After comparing the two very closely, you are sure these are the remains of the Wildhammer.  The treachery committed against them fills your heart with anger." }
WordHunterWoW_QuestEN[28804] = { title = "Dark Iron Contingency Plan", description = "These are definitely some sort of plans, but for what you aren't certain.  They bear distinctive markings that could be compared to a Dwarf Rune Stone.", objectives = "These are definitely some sort of plans, but for what you aren't certain.  They bear distinctive markings that could be compared to a Dwarf Rune Stone.", progress = "These are definitely some sort of plans, but for what you aren't certain.  They bear distinctive markings that could be compared to a Dwarf Rune Stone.", completion = "Interesting!  It seems as if the Dark Iron dwarves had a strategic plan in the case of an elemental invasion.  As the elemental forces are ageless and unchanging, it seems as if these ancient techniques are still viable even today." }
WordHunterWoW_QuestEN[28805] = { title = "The Eye of the Storm", description = "Greetings, {name}.\n\nYes, you are known to the Earthen Ring by name.\n\nYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A familiar presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the fate of our world.", objectives = "Farseer Krogar wants you to look into the Waters of Farseeing.", progress = "Yes, <class>?", completion = "Now that your eyes have seen the truth, where will you choose to serve?" }
WordHunterWoW_QuestEN[28806] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!" }
WordHunterWoW_QuestEN[28807] = { title = "Expert Opinion", description = "<Anduin holds up the matching badges.>\n\nThe medallion we found on the farm is identical to the one in Samuelson's notes! It can't be a coincidence. I think Samuelson is up to something, but we need a smoking gun before we can accuse one of my father's most trusted guards.\n\nThere's only one person I trust to sort this all out: Mathias Shaw, the director of SI:7. Show him these badges and see what he thinks. Meanwhile, I'll go back to the keep and watch Samuelson like a hawk!", objectives = "Bring the Suspicious Badges to Mathias Shaw at SI:7 Headquarters in Stormwind.", progress = "What's this you've brought me?", completion = "Anduin has been investigating the Twilight's Hammer? Weren't you supposed to keep him OUT of trouble?\n\nHmmm. Let me see those badges you've discovered." }
WordHunterWoW_QuestEN[28808] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!" }
