WordHunterWoW_QuestEN[28814] = { title = "Followers and Leaders", description = "The documents detail the arrival of High Priestess Azil to the depths of the Stonecore.\n\nAzil is described as a high-ranking member of the Twilight Council.  Additionally, her entourage of over a hundred devout followers is preparing for an unholy ritual of unforeseen darkness.\n\nSounds like an event you need to put a stop to.", objectives = "Slay High Priestess Azil and 101 Devout Followers.", progress = "You've returned, <name>.  What news do you bring?", completion = "A high priestess, you say?  And a member of the Twilight Council?\n\nExcellent work.  I hope you find your rewards suitable." }
WordHunterWoW_QuestEN[28815] = { title = "Twilight Documents", description = "We've tailed one of the Twilight's Hammer operatives here.  He goes by the name of Millhouse Manastorm.\n\nWe have reason to believe he's carrying important documents.\n\nThis is as far as we can safely go, however, without neglecting our duty to defend the Temple of Earth's inner perimeter.\n\nTrack down Manastorm and retrieve the documents from him.", objectives = "Obtain the Twilight Documents.", progress = "These appear to be the right documents.", completion = "<You open the documents and look for any noteworthy information.>" }
WordHunterWoW_QuestEN[28816] = { title = "To the Depths", description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies.\n\nIt is still uncertain what dangers might be faced there. Any information you could gather would be of great value.\n\nThe Horde is sending warships to the region as we speak. To gain passage, speak to Commander Thorak at Bladefist Bay.\n\nMay the spirits guide you, {name}.", objectives = "Report to Commander Thorak at Bladefist Bay in Durotar.", completion = "Lok'tar, brother! You have arrived just in time." }
WordHunterWoW_QuestEN[28817] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!" }
WordHunterWoW_QuestEN[28818] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!" }
