WordHunterWoW_QuestEN[28824] = { title = "Wayward Child", description = "One of my children is not with me, {name}.\n\nHe stayed behind with the Twilight's Hammer at the Stonecore deep within the Temple of Earth.\n\nI sent my other children to free him from the dark magic that was surely keeping him from returning here, but... no such magic was placed upon him.\n\nGo into the Stonecore and destroy Ozruk.  He must be reclaimed by the earth.", objectives = "Slay Ozruk.", progress = "Is it done, <race>?", completion = "<Therazane's eyes appear slightly more crystalline than you recall.>\n\nOzruk has been reclaimed by the earth.\n\nTake your reward and leave me be, <name>.  I wish to be left alone." }
WordHunterWoW_QuestEN[28825] = { title = "A Personal Summons", description = "<An unfamiliar feeling wells up from deep within you, flooding your mind with thoughts and images.>\n\nHear my words, {name}.\n\nOur world finds itself in the grip of a terrible crisis.\n\nI call upon you to lend your aid in this desperate hour.\n\nI am Naraat.\n\nSeek me out at once, and your calling shall be revealed.\n\nI await you at the Eastern Earthshrine in Stormwind City.", objectives = "Speak to Naraat the Earthspeaker in Stormwind.", completion = "May your sense of honor and duty serve Azeroth well, <class>." }
WordHunterWoW_QuestEN[28826] = { title = "The Eye of the Storm", description = "Greetings, hero of Azeroth.\n\nWe of the Earthen Ring know you by name, {name}.\n\nYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A powerful presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the dilemma of our world.", objectives = "Naraat the Earthspeaker wants you to look into the Waters of Farseeing.", progress = "Yes, <class>?", completion = "Now that your eyes have seen the truth, where will you choose to serve?" }
WordHunterWoW_QuestEN[28827] = { title = "To the Depths", description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies.\n\nIt is still uncertain what dangers might be faced there, so any information you could gather would be of great value.\n\nThe Alliance is sending warships to the region as we speak. To gain passage, travel northwest of Stormwind and speak to Recruiter Burns at Stormwind Harbor.\n\nMay the spirits guide you, {name}.", objectives = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City.", completion = "All of our war ships are off fighting the Horde. You'll have to take the mercenary ship." }
WordHunterWoW_QuestEN[28828] = { title = "You Gotta Have Eggs", description = "I don't have a very discerning palate, but even I can't stand the taste of those chimaeras that you'll find around here.  Their eggs, however, are a different story.\n\nChimaera eggs are the richest, most buttery eggs you'll find this side of Orgrimmar.  Way better than boring owl eggs, and not as sulfurous as those weird wildkin eggs.\n\nI'll take as many of them as you can gather.  Head northeast, and look for their nests in the snow.", objectives = "Obtain 40 Chillwind Eggs.", progress = "Mmmm....", completion = "Nice. Eggs.\n\nThese will go great with a little bear bacon.  Hey Francis, got any bear meat left over?" }
WordHunterWoW_QuestEN[28829] = { title = "Razor Beak and Antlers Pointy", description = "What happened to me, you ask?  Listen, {class}, and listen well, for my tale is one of tragedy...\n\nI was sent here to Owl Wing Thicket to find some relics.  I only made it this far before I was overwhelmed by a flurry of wings and talons.\n\nHow they roared and pecked, {class}!\n\nI now lay here, a broken orc, with nothing but vengeance on my mind. Please, {class}, if you have any sense of honor, you will go into Owl Wing Thicket and help me regain mine.", objectives = "Slay 12 Owlbeasts in Owl Wing Thicket.", progress = "They came at me two at a time, <class>.  I stood no chance.", completion = "My honor is restored.\n\nPartially.\n\nMy tale continues, <class>, for I have left portions of my honor elsewhere in this forest.\n\nIt has not been a very easy journey for me." }
WordHunterWoW_QuestEN[28830] = { title = "Chips off the Old Block", description = "My mysterious benefactors gave me more than one task. The second task took me farther south, to the Frostwhisper Gorge. I was surprised to learn that the gorge's bridge had been broken in two, preventing land travel from one side to the other.\n\nIn addition, the juvenile Frostmaul tumblers were separated from their stronger adult parents. I thought that I could defeat them in battle.\n\nI was incorrect. I was forced to run away in shame.\n\nTeach these tumblers a lesson, {name}. Fight them, and win.", objectives = "Slay 8 Frostmaul Tumblers.", completion = "Be glad that the adult giants are trapped on the other side of that gorge. They are far hardier than these tumblers you fight.\n\nI feel rejuvenated by your courage, <class>. Perhaps all hope is not lost after all..." }
WordHunterWoW_QuestEN[28831] = { title = "Damn You, Frostilicus", description = "The Frostmaul giants wouldn't have been a problem if it weren't for that damned Frostilicus. When the ground shook and the bridge broke, he and his fellow water elementals seeped out of the earth and took over the bottom of Frostwhisper Gorge, forcing the giants out.\n\nDamn you, Frostilicus!\n\nYou would do me a great honor if you would send him back into the ground, {class}. You will find him to the south, at the bottom of the gorge.", objectives = "Slay Frostilicus.", completion = "If I survive my wounds, I will always remember your name, <class>.\n\nWhenever the wind whistles through the trees, I will always hear your name.\n\nThank you." }
WordHunterWoW_QuestEN[28832] = { title = "Twilight Shores", description = "Right then, just hop in the seaplane behind me and I'll fly yeh to the Highlands.\n\nWe're to report to a feller named \"Lieutenant Fawkes.\" I've promised the King we'd get there lickety-fast, so I took the liberty of ditchin' any excess weight. Like seatbelts. Parachutes. Maps. Stabilizers. Landing gear.\n\nI never actually \"land\" these things anyways.", objectives = "Speak with Lieutenant Fawkes at Highbank in Twilight Highlands.", completion = "You two are the last thing I expected to see fall from the sky. Highbank is under attack!" }
WordHunterWoW_QuestEN[28833] = { title = "Rescue the Earthspeaker!", description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue Erunak.\n\nFight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives.\n\nDon't worry about them coming up from behind you. Nothing's making it past me!", objectives = "Rescue Erunak Stonespeaker.", completion = "What is this? You... rescuing me?\n\n<Erunak smiles at you.>\n\nThis will take some getting used to." }
WordHunterWoW_QuestEN[28834] = { title = "Rescue the Earthspeaker!", description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue Erunak.\n\nGo now. Fight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives.\n\nDon't worry about them coming up from behind you. I'll see that nothing makes it past me!", objectives = "Rescue Erunak Stonespeaker.", progress = "I thank you, my friend.", completion = "What is this? You... rescuing me?\n\n<Erunak smiles at you.>\n\nThis will take some getting used to." }
WordHunterWoW_QuestEN[28835] = { title = "Necessary Refreshment (Backup Groundspawn Quest)", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, <name>. If you bring me 6 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.You will receive:", objectives = "Obtain 6 Cactus Apples." }
WordHunterWoW_QuestEN[28836] = { title = "Sins of the Sea Witch", description = "That vile worm has earned a thousand deaths!\n\nIt won't be easy. She and her minions are firmly entrenched in this place, but she's bound to be exhausted from her fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity like this.\n\nRun her through, {name}!", objectives = "Slay Lady Naz'jar in the Throne of Tides.", completion = "Well done, <name>!\n\nKnow that without your aid, things would be far different here.\n\nNot only would I be long dead, but the naga and their allies would have free reign over the sea.\n\nThe king himself shall hear of your heroism in this realm." }
WordHunterWoW_QuestEN[28837] = { title = "Altered Beasts", description = "We, the blue dragons, have been forced out of our home, Mazthoril. An impostor by the name of Umbranse has taken advantage of us in our weakest hour, and now occupies the cave.\n\nMazthoril is a place of extremely potent magic, and he does not know how to wield it. Even the wildlife suffers.\n\nThe beasts nearby have been altered. Please, {race}, I must ask you a favor. Gather their brains, so I can see if I can undo this Umbranse's wild magic.", objectives = "Obtain 5 Mana-Addled Brains from Altered Beasts.", progress = "Mazthoril belongs to the blue dragonflight. This is not right.", completion = "Let's see what I can do with these..." }
WordHunterWoW_QuestEN[28838] = { title = "The Owlbeasts' Defense", description = "What a shame. Whatever Umbranse has done, he has prevented me from undoing his magic.\n\nHe is wiser than I had anticipated.\n\nI do have a backup plan, however. I have seen owlbeasts enter and leave Mazthoril, even after Umbranse took control. Their ancient druidic magic must be capable of disabling Umbranse's. Luckily, I happen to be somewhat of an expert in their methods.\n\nTravel south, to Dun Mandarr. You will find a chest with a dreamcatcher in it.\n\nThat will be your first step.", objectives = "Obtain an Owlbeast Dreamcatcher from Dun Mandarr.", progress = "The owlbeasts' magic will be the key to our retaking of Mazthoril.", completion = "Good. It is just as Jaron described it." }
WordHunterWoW_QuestEN[28839] = { title = "Magic Prehistoric", description = "The owlbeasts' sacred caves are located to the east. Within several of these caves, you should find totems. I want you to approach these totems and gather whatever essence you can from them. The dreamcatcher should absorb this essence for use within Mazthoril.", objectives = "Obtain the Essence of the Claw-Totem, the Essence of the Life-Totem, and the Essence of the Moon-Totem.", progress = "What are you doing, <name>? We need that essence.", completion = "The dreamcatcher is charged.  We are nearly ready to retake Mazthoril." }
WordHunterWoW_QuestEN[28840] = { title = "Winterwater", description = "I don't want our gambit to fail, {name}. Such a failure would only draw attention to our efforts, giving Umbranse an opportunity to hone his defenses. No, we have to do this right the first time.\n\nThe Frostwhisper Gorge, to the south, provides us access to powerful ice elementals. The water within these elementals' hulls should amplify the power of your dreamcatcher, ensuring our efforts.\n\nObtain this water, {name}. Then return to our small camp.", objectives = "Obtain 7 Winterwater from Ice Avatars in Frostwhisper Gorge.", progress = "Welcome back.", completion = "<Haleh applies the water to your dreamcatcher.>\n\nYou've done well, <name>." }
WordHunterWoW_QuestEN[28841] = { title = "The Arcane Storm Within", description = "Mazthoril's innate magic can wreak unimaginable havoc if mishandled. Umbranse's wanton casting within the cavern has opened up a number of tesseracts - in other words, portals - connecting to other worlds. If I am to return to Mazthoril, these tesseracts must be closed.\n\nThe dreamcatcher will close the portals, buying you safe entrance into Umbranse's lair. First defeat whatever comes out of the tesseracts, then use the dreamcatcher to quickly close them, before anything else spills into this world.", objectives = "Use the Empowered Dreamcatcher to close 5 Arcane Tesseracts within Mazthoril.", completion = "It will take some time for Mazthoril to recover... but she will.\n\nThe Blue Dragonflight is far from dead." }
WordHunterWoW_QuestEN[28842] = { title = "Umbranse's Deliverance", description = "Umbranse lurks in the back of Mazthoril. His time has come.\n\nUnfortunately, I am unable to join you on this quest. While I'd love to get my hands on that snake, Mazthoril's magic would rip me apart in its current state. No, I need you to finish this for me.\n\nWhen the deed is done, use this charm. It will return you safely to the egress.", objectives = "Slay Umbranse the Spiritspeaker.", progress = "You must finish this for me, <name>.", completion = "You have our thanks, <name>." }
WordHunterWoW_QuestEN[28843] = { title = "Sins of the Sea Witch", description = "Naz'jar! She's the one responsible for this mess.\n\nShe's in here somewhere, {name}. She must be exhausted after that fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity like this.\n\nI'll handle anything that tries to aid her from this direction.\n\nFind her, {name}, and run her through!", objectives = "Legionnaire Nazgrim wants you to slay Lady Naz'jar.", progress = "Is it done, <name>?", completion = "Hellscream shall know of your deeds here, <name>.\n\nWithout you, things here would be far worse.\n\nLok'tar ogar, my friend!" }
WordHunterWoW_QuestEN[28844] = { title = "Hyena Harvest", description = "Look, <name>!\n\nI have taken your bait and fashioned traps that will be most useful in your next task.\n\nFar to the southeast of here run a dangerous pack of Bloodsnarl Hyenas.\n\nI am confident that they can be tamed and used to great effect in our performance.\n\nLay one of these next to them and they won't be able to resist it.\n\nThen, once they're trapped, you just have to collect them and bring them back.\n\nIt works almost every time!You will receive:", objectives = "Use Sullah's Hyena Trap to capture 5 Bloodsnarl Hyenas." }
WordHunterWoW_QuestEN[28845] = { title = "The Vortex Pinnacle", description = "One of our civilian leaders was taken prisoner by the air elementals.\n\nThey are probably torturing him for information as we speak.\n\nGo to the Vortex Pinnacle, where these foul creatures came from, and look for Itesh.\n\nYou will find the entrance to the Vortex Pinnacle hovering off of the southeastern coast of Uldum.", objectives = "Find Itesh inside the Vortex Pinnacle.", completion = "You actually came here looking for me?" }
WordHunterWoW_QuestEN[28846] = { title = "Repel the Paratroopers Accepted Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[28847] = { title = "The Pursuit of Umbranse", description = "We have isolated Umbranse's position here in Winterspring. It is as I suspected.\n\nUmbranse is at Mazthoril, the cavern that once belonged to the blue dragonflight, in the southwest. My mother, Haleh, will greet you there. She is stationed outside of the cave in a small camp with a few other survivors.\n\nLook for her campfire.", objectives = "Report to Haleh at Beryl Egress in Winterspring.", completion = "You are <name>, yes?\n\nGood, you will serve well. I require the aid of a <class> such as yourself." }
WordHunterWoW_QuestEN[28848] = { title = "Trailing the Spiritspeaker", description = "I have heard tales of Umbranse, though I have not ever met him in person. Rumor has it that he's been collecting magical artifacts, though for what purpose, I couldn't say.\n\nBest pass this information on to a trusted ally. Nymn, the high elf, can be found within Everlook, the large goblin town to the northeast. Tell him all that we learned today.", objectives = "Report to Nymn at Everlook in Winterspring.", completion = "Umbranse... I see. I will carry this information onto my people.\n\nYou will be contacted if you are needed again." }
WordHunterWoW_QuestEN[28849] = { title = "Twilight Skies", description = "I just got word from Orgrimmar that the Warchief wants us to move out. We wouldn't have been ready if it wasn't for your help!\n\nThe plan is for the air fleet to take off immediately, and for the navy to follow close behind. Hellscream will be accompanying the air fleet and specifically requested that you come along with us.\n\nNo time to delay! Go to the Southern Rocketway Terminus here in Azshara, and check in with Friz Groundspin. I'll bring the zeppelin around to pick you up.", objectives = "Check in with Friz Groundspin at the Southern Rocketway Terminus in Azshara.", completion = "Another <class> for the Highlands? Here, sign this indemnification waiver..." }
WordHunterWoW_QuestEN[28850] = { title = "The Prison Rooftop", description = "I don't understand why the king wants to waste time saving his hide, but if you want to risk your life, then be my guest.\n\nCrowley and his men are holed up upstairs, probably plotting against the king as we speak!", objectives = "Speak to Darius Crowley upstairs in the Stoneward Prison in Gilneas City.", completion = "Greymane's right.  These beasts do not give a damn about our politics.\n\nGilneas needs to stand together." }
WordHunterWoW_QuestEN[28851] = { title = "Sullah's Sideshow", description = "Welcome, my friend!\n\nThe fruits of our labor have paid off abundantly! The time has come for us to give a dress rehearsal.\n\nOh, before we begin, I have a favor to ask.\n\nThere was a small snafu with a stubborn pygmy, so I have to ask that you take his place for the performance.\n\nI'm sure you'll be able to pick it right up. You're a natural!\n\nBreak a leg, my friend!You will receive:", objectives = "Speak to Sullah at Sullah's Sideshow.Welcome, my friend!\n\nThe fruits of our labor have paid off abundantly! The time has come for us to give a dress rehearsal.\n\nOh, before we begin, I have a favor to ask.\n\nThere was a small snafu with a stubborn pygmy, so I have to ask that you take his place for the performance.\n\nI'm sure you'll be able to pick it right up. You're a natural!\n\nBreak a leg, my friend!You will receive:" }
WordHunterWoW_QuestEN[28852] = { title = "Soften them Up", description = "At last, reinforcements! I'm so glad you're here. We never imagined just how entrenched the Twilight's Hammer forces are. And there are so many!\n\nSeveral of our drakes have been captured just inside the main hall. Please, break their bonds and free them.\n\nOnce free, together we can scourge these halls clean with flame. Just climb aboard a red drake and call out your targets. You will definitely want to cut down the enemy numbers before delving deeper into the ruins.", objectives = "Free a Red Drake within Grim Batol and use it to destroy 30 Troggs and 15 Twilight's Hammer minions.", completion = "This is great news, <name>! I'm glad our drakes were able to assist you. Thank you for rescuing them from the clutches of Twilight's Hammer." }
WordHunterWoW_QuestEN[28853] = { title = "Kill the Courier", description = "Thank you, {class}, for braving the horrors of this dark and terrible place.\n\nThe bowels of Grim Batol are the heart of Cho'gall's war machine. If we are to stop his machinations throughout the Highlands, we must learn all we can from these depths.\n\nSeek out Drahga Shadowburner within. He is Cho'gall's runner, the link between here and the Bastion of Twilight. We must learn the secrets he carries.", objectives = "Kill Drahga Shadowburner and grab his Missive to Cho'gall.", progress = "What have you discovered, <class>?", completion = "<Tooranu looks over the documents you discovered.>\n\nIt's all here, <name>. Details of how the cult is tearing up the Highlands, who they've sent, where they are, and what they plan to do. Invaluable.\n\nI shall distribute this knowledge to the rest of the Earthen Ring at once. Thank you, friend." }
WordHunterWoW_QuestEN[28854] = { title = "Closing a Dark Chapter", description = "This terrible place was Alexstrasza's nightmare. During what mortals call the second war, she was chained in the depths below, her tormented offspring forced to serve the demon-corrupted Horde.\n\nAlexstrasza may be free, but the beast known as Erudax still corrupts her offspring below.\n\n<Baleflame's body tenses in anger.>\n\nDestroy him, {class}. Crush him that we may end these horrors once and for all!", objectives = "Slay Erudax, the Duke of Below.", progress = "What of Erudax, <class>?", completion = "So it is done.\n\nWould that I could bring this entire mountain down upon itself, I would." }
WordHunterWoW_QuestEN[28855] = { title = "Northern Stranglethorn 4.x: PRK - E - Just Hatched FLAG", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[28856] = { title = "The Sands of Silithus", description = "Let's see... oh, here's a good one! Silithus!\n\nSo, apparently the Cenarion Circle needs assistance with an insect infestation of some sort.\n\n<Vizzie shivers.>\n\nUgh! No thanks, not for me. I'm perfectly happy freezing to death here in Everlook if the alternative is bugs.\n\nHmm... it says here that visitors should speak with Windcaller Proudhorn, and the easiest way to get there is via the path up Un'Goro Crater's northwestern cliffs.\n\nYou interested?", objectives = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Welcome to Cenarion Hold.\n\n<Windcaller Proudhorn brushes some snow off of your shoulder.>\n\nYou've certainly come from far off." }
WordHunterWoW_QuestEN[28857] = { title = "Blasted Lands: The Other Side of the World", description = "Now here's an interesting one. It says to report to Quartermaster Lungertz at Nethergarde Keep, in the Blasted Lands. That's just about as far as you can get from here!\n\nIt says they're having trouble with Horde attacks. Hmph! I didn't know the Horde even had an outpost in the Blasted Lands! They tend to worry more about demons and less about rivalries down there, as I understand it.\n\nYou'll have to cross the Great Sea, then travel south from the Swamp of Sorrows.\n\nYou interested?", objectives = "Report to Quartermaster Lungertz at Nethergarde Keep.", completion = "For decades has the garrison at Nethergarde held firm against the threat of the Horde and we do not intend to surrender now." }
WordHunterWoW_QuestEN[28858] = { title = "Blasted Lands: The Other Side of the World", description = "Now here's an interesting one.  It says that members of the Horde should talk to Okrilla at Dreadmaul Hold.\n\nHmph! I didn't even know that the Horde held Dreadmaul Hold!\n\nI guess this Okrilla requires help fighting some ogres and the Alliance. You'd think she'd already have her hands full with all the demons down there!\n\nThe best way to Dreadmaul Hold is to cross the Great Sea, then to take the road south from the Swamp of Sorrows.\n\nYou interested?", objectives = "Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", completion = "Our enemies are numerous, <class>. It will take skill and bravery to overcome them all." }
WordHunterWoW_QuestEN[28859] = { title = "The Dunes of Silithus", description = "Cenarion Hold, in Silithus, is one of the biggest druid settlements in Kalimdor. Almost as big as Moonglade, mon.\n\nSomeday, maybe Zen'Aliri be headin' on over to Cenarion Hold... fightin' some Twilight's Hammer, healin' the land where the silithid tear it... but Zen'Aliri's master tells him to wait.\n\nSo Zen'Aliri waits.\n\nThe easiest way to get there is that path up Un'Goro Crater's northwestern cliffs.\n\nIf you got no master... there's nothing keepin' you from movin' on.", objectives = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Welcome to Cenarion Hold, traveler." }
WordHunterWoW_QuestEN[28860] = { title = "Keeping the Dragonmaw at Bay", description = "With your help we've thumped the Dragonmaw pretty hard, but still their daily attacks in the Thundermar outskirts persist. We need to keep up the pressure!\n\nWade back into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear.", objectives = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "How goes the fight, <class>?", completion = "Aye, that's how it's done! With heroes like you taking care of business, I'm proud to be a part of the Alliance." }
WordHunterWoW_QuestEN[28861] = { title = "Fight Like a Wildhammer", description = "<Blundy upends his cup.>\n\nI'm all outta ale, {name}!\n\nHead out into the Thundermar Ruins and see if there's any left, before those grungy Dragonmaw get their mouths on it.\n\nFeel free to have a few sips, yerself. A mug of ol' Thundermar's finest will fortify yer fightin' skills.", objectives = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Carfeul - it's got some kick!", progress = "Got sumthun'?", completion = "Oh aye, quite a haul!\n\nThis'll last me until... oh say probably tomorrow." }
WordHunterWoW_QuestEN[28862] = { title = "Never Leave a Dinner Behind", description = "Refugees are still pouring into Thundermar from the fighting, and I'm hungry! I mean them. The refugees, they're hungry.\n\nGet me some food from the Thundermar Ruins! Scour the ruins to the south, east, and southwest for any stores that still remain. Especially them big hocks of ham. I love those! Er, the refugees do.\n\nAnd see if you can find some of them little cocktail weenies.", objectives = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Got some eats?", completion = "Oh hey, yer just in time! I was working up a huge appetite, workin' so hard to feed these hungry refugees. Yessir." }
WordHunterWoW_QuestEN[28863] = { title = "Warlord Halthar is Back", description = "He's at it again, {name}. Warlord Halthar... terror of the shire. He and his drake were spotted causing trouble to the south, among the Thundermar Ruins.\n\nKill Halthar, {name}! We'll send in some warbrands to help out once you engage.", objectives = "Slay Warlord Halthar.", completion = "Grim business, but well done all the same. Thank you, <name>." }
WordHunterWoW_QuestEN[28864] = { title = "Beer Run", description = "After my sister's wedding, I developed a taste for that Thunderbrew Lager that Kurdran had imported from Dun Morogh. More is on the way, but our caravan keeps getting jumped by the Dragonmaw!\n\nHead on up to the southeast side of Thunderstrike Mountain and catch up with the caravan. Look for a fellow named Hammelhand at the side of the road, and help him get the booze through the pass.\n\nJust get it as far as Kirthaven, and we'll take it from there.", objectives = "Speak with Hammelhand on the road southeast of Thunderstrike Mountain and escort a supply caravan to Kirthaven.", completion = "Go figure. Never thought I'd develop a taste for imported draft. Thanks, <name>!" }
WordHunterWoW_QuestEN[28865] = { title = "Call of the Warmatron", description = "Our venerable warmatron, Okrilla, has sent me to the far reaches of the world in search of suitable heroes that would join our cause. Are you interested in strengthening the Horde's grasp over the Eastern Kingdoms? Then take this portal to the Blasted Lands and report to Okrilla at Dreadmaul Hold!", objectives = "Report to Okrilla at Dreadmaul Hold in Blasted Lands.", completion = "Silithus, such a worthless piece of land. It is a wonder that the great cataclysm did not sunder it fully!" }
WordHunterWoW_QuestEN[28866] = { title = "Into the Stonecore", description = "You say that this Millhouse Manastorm and High Priestess Azil were to meet inside the Stonecore?\n\nSounds big.  We'd best get on their trail.  We don't want the Twilight's Hammer pulling off something big right under our noses.\n\nSpeak to Earthwarden Yrsa inside the Stonecore.  She's been stationed there to make sure the Twilight's Hammer doesn't try to retake the Temple of Earth.", objectives = "Speak to Earthwarden Yrsa inside the Stonecore.", completion = "It's about time they sent someone to help.\n\nMillhouse Manastorm?  It sounds like we're both after the same person." }
WordHunterWoW_QuestEN[28867] = { title = "Nethergarde Needs You!", description = "Nethergarde needs you, {class}! I have been sent here by Quartermaster Lungertz to head off Okrilla's nefarious lackeys and to recruit able-bodied heroes of the Alliance! Help us fight off the Horde!\n\nIf you are willing, take this portal in front of me to the Blasted Lands and speak with the quartermaster.", objectives = "Speak to Quartermaster Lungertz at Nethergarde Keep in Blasted Lands.", completion = "Silithus, not such a great place, eh? We get a lot of you from there..." }
WordHunterWoW_QuestEN[28868] = { title = "The View from Down Here", description = "We need to halt the construction on this Frostmane village. If we let them get too entrenched, it will be more difficult to keep them from settling here permanently.\n\nIt's time to give those brutes a gnome's-eye view of the world! Take this gnomish viewpoint equalizer and use it on the Frostmane builders to bring them down to our level. They won't be able to lift their tools and construction will come to a standstill.", objectives = "Use the Viewpoint Equalizer on 5 Frostmane Builders in Frostmane Retreat.", progress = "Did you show them what it's like to be a gnome?", completion = "Well done, <name>. That'll teach them not to mess with us in our home!" }
WordHunterWoW_QuestEN[28869] = { title = "Pebble", description = "If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him.\n\nYou seem to be quite adept at making friends down here. A good talent to have.", objectives = "Speak to Pebble in the Shuddering Spires. If you stay on the ground long enough, he should come out of hiding to find you.If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him.\n\nYou seem to be quite adept at making friends down here. A good talent to have.", completion = "<Pebble seems quite happy to meet you.>" }
WordHunterWoW_QuestEN[28870] = { title = "Return to the Lost City", description = "We might've taken Neferset City, but the Neferset have a new seat of power.\n\nThanks to Siamat, the powerful djinn of the south wind, the Neferset have become considerably more dangerous.\n\nWe just learned that some of Nadun's ambushed reconnaissance party managed to secure the entrance to the Lost City.\n\nGo find Captain Hadan and get whatever information you need to bring down Siamat and the Neferset scum.", objectives = "Speak to Captain Hadan inside the Lost City of the Tol'vir.", completion = "Hail, <name>.  Nadun spoke highly of you.\n\nAre you here to aid us?" }
WordHunterWoW_QuestEN[28871] = { title = "Crushing the Wildhammer", description = "The Wildhammer grow bold with their new Alliance allies. They dare press across the river. Drive them back!\n\nSeek out and crush the Wildhammer warbrands who fight in the riverbed and within the Thundermar Ruins along the north bank. The best among them carry insignias - gather them for me to prove your allegiance to the Dragonmaw cause.", objectives = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "Show me the insignias you've collected, <class>.", completion = "Look what we have here! A single Horde <class> can demolish the Wildhammer by the dozen. What hope do they have now?" }
WordHunterWoW_QuestEN[28872] = { title = "Total War", description = "Some of the Wildhammer still cling to the hope of reclaiming the Thundermar Ruins to the north, across the river. Burn them out! Smash open kegs of Thundermar ale. That wicked brew is potent enough to explode when set aflame.\n\nDon't ask me why.\n\nAnd don't ask me how they drink the stuff.", objectives = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, <name>." }
WordHunterWoW_QuestEN[28873] = { title = "Another Maw to Feed", description = "<Griff's stomach growls.>\n\nStill hungry. It's like ... every day, I'm hungry.\n\nI hear there's more food stashed up in the Thundermar Ruins across the river to the north, where all the fighting is. Bring some to my mouth.", objectives = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "<Griff licks his lips.>", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! This'll tide me over for ... hours!" }
WordHunterWoW_QuestEN[28874] = { title = "Hook 'em High", description = "The Wildhammer can train war gryphons faster than we can subvert and control drakes. We can't let them continue to outnumber us!\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Kill the dismounted gryphon riders!", objectives = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", completion = "You made that look easy, <name>.\n\nGet the Wildhammer off of their mounts and they're nothing!" }
WordHunterWoW_QuestEN[28875] = { title = "Bring Down the High Shaman", description = "Our scouts in the field report that High Shaman MacKilligan has moved out of Thundermar and is fighting amidst the Thundermar Ruins northwest of here, across the river.\n\nHe's a dangerous one, {name}, responsible for the deaths of many a Dragonmaw. He WILL be destroyed, that is not the question.\n\nThe question is: will you be the one to earn the glory of the kill?", objectives = "Slay High Shaman MacKilligan.", completion = "The High Shaman has been brought down! Thundermar will no doubt try to send others, but on this day, the Dragonmaw are triumphant." }
WordHunterWoW_QuestEN[28876] = { title = "To the Mor'shan Rampart", description = "Kadrak at the Mor'shan Rampart to the north is calling for aid.\n\nThe rampart rests on the border between the Northern Barrens and Ashenvale. It is the front line in the fight against the Alliance.\n\nWe're driving the night elves out of the forest. We'll claim its resources for the Horde!\n\nTo get there, take the Gold Road north out of the Crossroads.\n\nDestiny calls!", objectives = "Report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale.", completion = "You're the reinforcements that Thork sent?\n\nYou'll do fine as long you can kill night elves. The forest is crawling with them." }
WordHunterWoW_QuestEN[28877] = { title = "They Call Him Swiftdagger. He Kills Harpies.", description = "There's an orc who lives in the west. At the frayed edge of the cataclysm's swath of destruction.\n\nThey call him Swiftdagger, <name>. They call him that because ... his ... actually I think that's just his name.\n\n<Nozzlepot shrugs.>\n\nAnyway, he's a harpy-killing machine. He kills harpies. Loves it. It's a living. Go and see him! See how it's done. Live the dream. You might make a career out of it.", objectives = "Locate Darsok Swiftdagger in Northern Barrens.", completion = "I suppose my reputation grows. Yes, yes I kill harpies. I don't enjoy it. But their raids on our supply caravans must cease, and someone's got to organize a resistance." }
WordHunterWoW_QuestEN[28878] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[28879] = { title = "Back To The Orphanage", description = "We had the best time with you, {name}. We wish you could be our daddy now, but you have to take us back to Orphan Matron Aria in Dalaran.\n\nMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!\n\nWe going to miss you, {name}. We promise to write letter sometime, oki? ", objectives = "Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.", completion = "It sounds like little Roo had a great time this week. I know he was getting awfully lonely in the orphanage and was eager to make some new friends. Thank you so much for agreeing to look after him." }
WordHunterWoW_QuestEN[28880] = { title = "Back To The Orphanage", description = "Know what? You not so bad after all, {name}. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.\n\nYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.\n\nKekek gotta go back to orphan-lady Aria now, back in purple human city.", objectives = "Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.", completion = "Thank you for agreeing to care for Kekek this week. I know he can be a handful, but I think that with more individual attention and a few more friends, he'll do a lot better. No doubt he's going to be telling stories of his adventures with you for weeks." }
WordHunterWoW_QuestEN[28881] = { title = "Prospector Gunstan", description = "Say... you haven't been to Southmoon Ruins yet, have you?  Oh you simply MUST.  They have all sorts of fascinating titan artifacts.  Head west, and look for the Explorers' League tents.", objectives = "Report to Prospector Gunstan at Southmoon Ruins in Tanaris.", completion = "What, you here to help?" }
WordHunterWoW_QuestEN[28882] = { title = "Victory in Tol Barad", description = "We fought hard to get a foothold on this ugly rock and there is no way we are going to let the Horde get in the way of our plans.  Keeping control of Tol Barad is our first priority and we need your help, {name}.  Fight your way to victory in Tol Barad and return to me word of your triumph.", objectives = "Win a Tol Barad battle and return to Major Marsden at Baradin Base Camp in Tol Barad Peninsula.", progress = "Were you victorious against the Horde?", completion = "What's that smell?  Ah.....Smells like victory.  Your efforts in Tol Barad are a great triumph for the entire Alliance, your contributions will not be forgotten." }
WordHunterWoW_QuestEN[28884] = { title = "Victory in Tol Barad", description = "Maintaining control of Tol Barad is the key to our strategic plans here in the Eastern Kingdoms, {race}.  We must do whatever it takes to keep the Alliance off this island and that means we need your help.  Fight with everything you have to win control of Tol Barad and bring me word of victory.", objectives = "Win a Tol Barad battle and return to Colonel Karzag at Hellscream's Grasp in Tol Barad Peninsula.", completion = "You bring word of victory, just as I expected!  Any triumph in Tol Barad is in turn a triumph for the Horde.  Have no doubt, your efforts here will be rewarded." }
WordHunterWoW_QuestEN[28885] = { title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", objectives = "Ride the mine cart with Initiate Goldmine to the end of the line.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!" }
WordHunterWoW_QuestEN[28886] = { title = "Frost Instructions Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[28887] = { title = "Fire Insutrctions Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[28888] = { title = "Shadow Instructions Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[28889] = { title = "Arcane Instructions tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[28890] = { title = "Wasteland", description = "This is Silithus, <class>... a harsh and brutal wasteland. Few know that an ancient war was waged here between the night elves and a malign, alien power. The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.\n\nSeek out Layo Starstrike, one of my agents. I have sent him to the southeast to investigate the ruins of Southwind Village.\n\nGive him this letter, and he will give you his trust accordingly.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver Rabine's Letter to Laylo Starstrike near Southwind Village." }
WordHunterWoW_QuestEN[28891] = { title = "The Spirits of Southwind", description = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, <name>.\n\nFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...\n\nThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village." }
WordHunterWoW_QuestEN[28892] = { title = "Hive in the Tower", description = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.\n\nThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the Encrusted Silithid Object." }
WordHunterWoW_QuestEN[28893] = { title = "Umber, Archivist", description = "Analyzing this is key. If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!\n\nGive this to my friend over there.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Encrusted Silithid Object to Umber." }
WordHunterWoW_QuestEN[28894] = { title = "Uncovering Past Secrets", description = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with our dear \"den mother\" Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, <name>... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Rabine Saturna at Cenarion Hold in Silithus.Anyway, you should check back with me relatively soon... that is if you want to know what was in here. As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with our dear \"den mother\" Rabine. No doubt he'll want to know what crazy antics you've been up to. Never leave the den mother waiting, <name>... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[28895] = { title = "Befoulers of the Wind", description = "You are foolish to even have come to a place such as this, <class>. But I might have use for even a fool.\n\nI stand vigil here over my master's prison, keeping watch across the years. Nothing may interrupt me. Not even the disgusting minions of the earth that roam here, intruders upon the territory of wind...\n\nI despise them! I destroy those that venture close, but I cannot allow myself to waste time on such pests. If you were to do so, however, I could reward you for it...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 10 Desert Rumblers." }
WordHunterWoW_QuestEN[28896] = { title = "Recalling", description = "The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon, and above them is a code... I know this code. I deciphered it when the gates of Ahn'Qiraj reopened.\n\nBut the Qiraji are long defeated... who is controlling the silithid with this? Take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold. Use them there and see who shows up. They likely won't be friendly... be careful.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Glyphs of Calling at the Bones of Grakkarond to summon the new master of the silithid." }
WordHunterWoW_QuestEN[28897] = { title = "Baristolth's Plan", description = "The guards here mentioned they've seen the Twilight's Hammer cultists moving closer to Hive'Ashi recently. Could they be amassing forces inside the hive, in secret?\n\nWe've got to get to the bottom of this before they have a chance to put whatever foul plot they're brewing into motion.\n\nBaristolth, the hunter just across the way in front of me, has hunted through the hives of Silithus since before you or I were born. He may have a way for you to get inside Hive'Ashi unnoticed...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Baristolth of the Shifting Sands in Cenarion Hold.The guards here mentioned they've seen the Twilight's Hammer cultists moving closer to Hive'Ashi recently. Could they be amassing forces inside the hive, in secret?\n\nWe've got to get to the bottom of this before they have a chance to put whatever foul plot they're brewing into motion.\n\nBaristolth, the hunter just across the way in front of me, has hunted through the hives of Silithus since before you or I were born. He may have a way for you to get inside Hive'Ashi unnoticed...You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[28898] = { title = "Secretion and Subterfuge", description = "I've seen no cultists wandering the surface of Hive'Ashi to the north. With any luck, we can make our preparations without being noticed.\n\nOne of the organs of the silithid is used to secrete a thick sludge that hardens in the air. This is used to build hives, and by some to lay eggs.\n\nBring me enough of these organs to cover someone twice your height, and do not venture far into the hives just yet.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 8 Hive'Ashi Secretion Glands from any Silithid in Hive'Ashi." }
WordHunterWoW_QuestEN[28899] = { title = "Riding in Plain Sight", description = "We are prepared. Take this box. Upon opening it, you will be engulfed in silithid mucus and encased within a temporary egg. \n\nUse it near other eggs on the surface of Hive'Ashi, and the drones should carry you within the hive, unknown to their twilight guardians. The egg should break before you run out of air.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Primed Silithid Mucous near the Hive'Ashi Egg pile to infiltrate the hive." }
WordHunterWoW_QuestEN[28900] = { title = "Mysteries of the Twilight Hive", description = "It's as we suspected... this hive is a hidden base of operations for the Twilight's Hammer cult. They have kept their increased activity a secret this way.\n\nWe must find what they are plotting. Search the hive for any clues to their plans, and make sure you leave enough of the lunatics dead to keep them from further scheming.You will receive:", objectives = "Search Hive'Ashi for evidence of the Twilight Hammer's plot, and kill 10 Twilight's Hammer cultists." }
WordHunterWoW_QuestEN[28901] = { title = "Prisoners of Madness", description = "You! Come here! Yes, to the egg! I can just barely see you.\n\nIt looks like Baristolth improved his disguise before you tried it... I'm still stuck in this thing. I'm the scout he sent ahead here.\n\nNo, no, there's no time to assist me! You have to help the others! They've got prisoners all throughout this hive... Find them and rescue them.\n\nI'll get out of this thing myself... how hard could it be?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue 5 Hive'Ashi Prisoners." }
