WordHunterWoW_QuestEN[28909] = { title = "Sauranok Will Point the Way", description = "I see you haven't yet spoken to the Warchiefs... other... advisor, Sauranok the Mystic. He has been at their side since our campaign together in Northrend.\n\nTo assault the Twilight Highlands, we're going to need a map of the shoreline. I have tasked Sauranok with digging up this information. See if he can use your assistance!", objectives = "Speak with Sauranok the Mystic at Grommash Hold in Orgrimmar.", completion = "<Sauranok nods toward you.>\n\n<class>." }
